  const floorGeom = new THREE.BoxGeometry(FLOOR_WIDTH, 1, FLOOR_LENGTH);
  const floor = new THREE.Mesh(floorGeom, floorMat);
  floor.position.y = -0.5; 
  stageGroup.add(floor);

